// Grundlagenmodul + Lektionen 1–6 (Offenbarungsreihenfolge, Kairoer Chronologie)
window.GRUNDLAGEN = {
  titel: "Grundlagen: Wie du den Koran im Kontext liest",
  kurz: "Bevor du mit Sure 96 startest: Was Offenbarung bedeutet, warum die Reihenfolge im Buch nicht die Reihenfolge der Herabsendung ist, was Asbāb an-Nuzūl sind, woran man guten Tafsir erkennt, wie Hadith-Quellen funktionieren – und was die hanafitische Rechtsschule ist.",
  abschnitte: [
    {t: "Was ist der Koran – und wie kam er herab?",
     p: ["Der Koran ist für Muslime das wörtliche Reden Allahs (kalāmullāh), das dem Propheten Muhammad ﷺ über den Engel Dschibrīl (Gabriel) offenbart wurde – nicht auf einmal, sondern über etwa 23 Jahre (ca. 610–632 n. Chr.). Diese schrittweise Herabsendung heißt tanzīl. Der Koran selbst nennt den Grund: „… damit Wir dein Herz damit festigen. Und Wir haben ihn wohlgeordnet vorgetragen.“ (25:32). Die Offenbarung reagierte also auf echte Situationen: Fragen der Gefährten, Angriffe der Gegner, Krisen, Siege. Genau deshalb ist Kontext kein Extra, sondern der Schlüssel.",
       "ʿĀʾischa (möge Allah mit ihr zufrieden sein) beschreibt, wie die Offenbarung begann: zuerst wahre Träume, dann die Begegnung in der Höhle Ḥirāʾ (Sahih al-Buchari, Nr. 3). Die Offenbarung kam in verschiedenen Formen – mal wie Glockenklang, der am schwersten war, mal sprach der Engel direkt (Sahih al-Buchari, Nr. 2)."]},
    {t: "Mekkanisch und medinensisch – zwei Phasen, zwei Tonlagen",
     p: ["Rund 86 Suren gelten als mekkanisch (vor der Hidschra 622 n. Chr.), 28 als medinensisch. Mekkanische Suren sind meist kurz, rhythmisch, erschütternd: Sie bauen das Fundament – Tauhīd (Allahs Einheit), Auferstehung, Gericht, Prophetenschaft, Charakter. Medinensische Suren sind länger und regeln das Leben der neuen Gemeinschaft: Gebet im Detail, Fasten, Zakat, Familienrecht, Verträge, Krieg und Frieden, Umgang mit Juden, Christen und Heuchlern.",
       "Das ist der wichtigste Lernschlüssel überhaupt: Erst 13 Jahre Herzensbildung, dann 10 Jahre Gesetzgebung. Wer Rechtsverse liest, als wären sie ohne dieses Fundament und ohne ihre Situation gesprochen, versteht sie falsch – in beide Richtungen: der Extremist reißt sie aus dem Kontext heraus, der Verlegene erklärt sie weg. Beides ist Unwissen."]},
    {t: "Warum die Buchreihenfolge nicht die Offenbarungsreihenfolge ist",
     p: ["Im Mushaf (Buch) steht Al-Baqara vorne, aber die erste Offenbarung waren fünf Verse von Sure 96 (Al-ʿAlaq). Die Anordnung im Buch gilt nach Mehrheit der Gelehrten als tauqīfī – vom Propheten ﷺ auf Anweisung Dschibrīls festgelegt. Beide Ordnungen haben Sinn: Die Buchordnung ist die Ordnung der Rezitation und des Gottesdienstes; die Offenbarungsordnung ist die Ordnung der Erziehung – sie zeigt, wie Allah eine Generation Schritt für Schritt aufgebaut hat.",
       "Diese App folgt als rotem Faden der Offenbarungsreihenfolge nach der Kairoer Standard-Chronologie (Azhar-Ausgabe von 1924), die auf den klassischen Überlieferungen (u. a. Ibn ʿAbbās) beruht. Wichtig: Die Chronologie ist in den Grundzügen gesichert (was früh ist und was spät), im Detail aber bei manchen Suren unter Gelehrten umstritten – das ist normal und kein Problem für das Verständnis."]},
    {t: "Asbāb an-Nuzūl: die Offenbarungsanlässe",
     p: ["Asbāb an-Nuzūl („Gründe der Herabsendung“) sind die überlieferten Situationen, zu denen bestimmte Verse offenbart wurden. Die zwei Standardwerke dazu: „Asbāb an-Nuzūl“ von al-Wāḥidī (gest. 1076) und „Lubāb an-Nuqūl“ von as-Suyūṭī (gest. 1505). Nicht jeder Vers hat einen Anlass – viele wurden ohne konkretes Ereignis offenbart.",
       "Eine Grundregel der Gelehrten musst du kennen: al-ʿibra bi-ʿumūm al-lafẓ lā bi-ḫuṣūṣ as-sabab – „Maßgeblich ist der allgemeine Wortlaut, nicht nur der besondere Anlass.“ Heißt: Der Anlass erklärt, worauf ein Vers zielt und begrenzt wilde Fehldeutungen – aber der Vers bleibt als Lehre allgemein gültig. Beispiel: Ein Vers über einen konkreten Heuchler warnt jeden vor Heuchelei. Der Anlass ist die Brille, nicht der Käfig."]},
    {t: "Woran erkennt man verlässlichen Tafsir?",
     p: ["Die klassische Methode (so beschreibt sie Ibn Kathīr in seiner Einleitung) erklärt den Koran in dieser Rangfolge: (1) Koran durch Koran – ein Vers erklärt den anderen. (2) Koran durch die Sunna – der Prophet ﷺ ist der lebendige Kommentar. (3) Die Aussagen der Sahāba (Gefährten), die die Offenbarung miterlebt haben, allen voran Ibn ʿAbbās. (4) Die Tābiʿūn (Schülergeneration, z. B. Mudschāhid, Qatāda). (5) Die arabische Sprache zur Zeit der Offenbarung.",
       "Die Hauptwerke, auf die sich diese App stützt: aṭ-Ṭabarī (gest. 923, das Mutterwerk mit allen Überlieferungen), Ibn Kathīr (gest. 1373, hadithbasiert und zuverlässig), al-Qurṭubī (gest. 1273, stark bei Rechtsfragen), as-Saʿdī (gest. 1956, einfach und klar – ideal für Einsteiger). Für hanafitische Rechtsauslegung: „Aḥkām al-Qurʾān“ von al-Dschaṣṣāṣ (gest. 981), dem großen hanafitischen Korankommentator."]},
    {t: "Hadithe richtig einordnen",
     p: ["Ein Hadith ist eine Überlieferung über Worte, Taten oder Billigungen des Propheten ﷺ. Jeder Hadith hat eine Überliefererkette (isnād) und einen Text (matn). Die Gelehrten prüften jede Kette und stuften ein: ṣaḥīḥ (authentisch), ḥasan (gut), ḍaʿīf (schwach), mauḍūʿ (erfunden). Die zwei verlässlichsten Sammlungen sind Sahih al-Buchari und Sahih Muslim; danach die vier Sunan-Werke (Abū Dāwūd, at-Tirmidhī, an-Nasāʾī, Ibn Mādscha).",
       "In dieser App werden Hadithe immer mit Werk und Nummer zitiert (z. B. „Sahih al-Buchari, Nr. 3“), damit du alles nachschlagen kannst – etwa auf sunnah.com. Wenn eine Überlieferung nur in Tafsir-Werken steht und nicht sahih-geprüft ist, steht das ausdrücklich dabei."]},
    {t: "Die hanafitische Rechtsschule – dein Fiqh-Rahmen",
     p: ["Die hanafitische Madhhab geht auf Imam Abū Ḥanīfa (gest. 767 n. Chr. / 150 n. H.) zurück, ausgearbeitet von seinen Schülern Abū Yūsuf und Muhammad asch-Schaibānī. Sie ist die am weitesten verbreitete Rechtsschule der Welt (Türkei, Balkan, Zentralasien, Indien/Pakistan u. a.) und bekannt für systematisches Denken und Differenzierung.",
       "Zwei Besonderheiten, die dir hier oft begegnen werden: Erstens unterscheiden Hanafiten zwischen farḍ (durch eindeutigen Beleg verpflichtend – wer es leugnet, verlässt den Islam) und wādschib (durch starken, aber nicht hundertprozentig eindeutigen Beleg verpflichtend – wer es auslässt, sündigt, aber bleibt Muslim). Andere Schulen kennen diese Trennung so nicht. Zweitens: Im Kriegs- und Strafrecht urteilen Hanafiten konsequent danach, dass Grund des Kampfes die Aggression (muḥāraba) ist, nicht der Unglaube an sich – das wird bei den Brennpunkt-Versen wichtig.",
       "Ehrlichkeit gehört zum Lernen: Wo die Schulen verschieden urteilen, sagt dir die App die hanafitische Position und erwähnt, dass es andere gibt. Und: Diese App ersetzt keinen Gelehrten. Für konkrete Fatwa-Fragen frag qualifizierte hanafitische Gelehrte."]},
    {t: "Wie du mit dieser App lernst",
     p: ["Der Lernpfad folgt der Offenbarungsreihenfolge. Jede Lektion hat denselben Aufbau: Kurzzusammenfassung (das Wichtigste in 60 Sekunden) → Kontext & Zeit → Offenbarungsanlässe mit Quelle → Arabische Schlüsselbegriffe mit Wurzel → Tafsir in Sinnabschnitten → Authentische Hadithe → Hanafitische Hinweise (wo relevant) → Umsetzung im Alltag.",
       "Empfehlung: Eine Lektion pro Tag oder pro Woche – aber mit Mushaf daneben. Lies die Sure einmal auf Arabisch (oder höre sie), lies die Übersetzung, dann die Lektion, dann die Sure noch einmal. Du wirst sie mit anderen Augen lesen. Markiere die Lektion erst als abgeschlossen, wenn du sie jemandem in drei Sätzen erklären könntest – das ist der Test echten Verstehens."]}
  ]
};

